# The reflex cycle, conceptually: fixed work per tick, hard deadline
def reflex_tick(state, T_loop_s):
    x  = read_validated_state()      # bounded: fixed channel count
    u  = bounded_control_law(x)      # affine / lookup, no iteration
    u  = envelope_clamp(u, x)        # range + rate-of-change limits
    if not within_envelope(x):
        return drive_failsafe()      # single-cycle escape
    return gate_actuators(u)

# deadline == period: the loop must finish inside its own tick
assert wcet(reflex_tick) < T_loop_s

import math
def loop_period(f_bw_hz, oversample=30):
    # sample well above the closed-loop bandwidth to bound phase lag
    fs = oversample * f_bw_hz
    return 1.0 / fs                      # loop period, seconds

def phase_lag_deg(T_loop, f_bw_hz):
    # half-sample computational delay -> phase lag at bandwidth
    return 360.0 * f_bw_hz * (T_loop/2.0)

T = loop_period(2_000)                   # 2 kHz mode -> ~17 us period
print(round(phase_lag_deg(T, 2_000),1)) # ~6 deg lag at bandwidth

def wcet_ns(cycles, clk_hz):
    return cycles / clk_hz * 1e9

# a validation + control-law block: fixed pipeline depth
print(round(wcet_ns(cycles=250, clk_hz=250e6), 1))   # 1000.0 ns

def path_wcet(stage_cycles, clk_hz):
    # sum of fixed-depth stages: still exact, no distribution
    return sum(wcet_ns(c, clk_hz) for c in stage_cycles)

def gate(cmd_valid, state_permits, interlocks_clear, in_window):
    # all four must be true in the same cycle for the gate to open
    return cmd_valid and state_permits and interlocks_clear and in_window

def in_actuation_window(t, t_edge_ns, width_ns=200):
    # phase-locked window: pellet/beam/coil edges align to the clock
    return 0 <= (t - t_edge_ns) <= width_ns

def phase_locked_commit(actuators, fire_edge_ns, prepare_deadline_ns, now_ns):
    armed = [a for a in actuators if a.arm()]        # phase 1: prepare
    if len(armed) != len(actuators) or now_ns > prepare_deadline_ns:
        for a in armed: a.disarm()                   # atomic abort
        return 'aborted'
    for a in armed:
        a.schedule_fire(fire_edge_ns)                # phase 2: same edge
    return 'committed'

def accept_setpoint(sp, live_envelope, age_ms, max_age_ms=150):
    if age_ms > max_age_ms:
        return holding_law()             # stale supervisory link
    if not live_envelope.contains(sp):
        return live_envelope.clamp(sp)   # trust, but verify + clamp
    return sp

def response_time(i, C, T, D):
    # C=WCETs, T=periods, D=deadlines; tasks sorted by deadline (i highest prio first)
    R = C[i]
    while True:
        interference = sum(-(-R // T[j]) * C[j] for j in range(i))  # ceil()
        R_new = C[i] + interference
        if R_new == R:
            return R <= D[i], R      # schedulable if response <= deadline
        if R_new > D[i]:
            return False, R_new
        R = R_new

def failsafe_trip(signals, thresholds, heartbeat_ok, power_ok):
    # pure combinational logic: any breach OR loss of liveness -> trip
    breach = any(s > t for s, t in zip(signals, thresholds))
    if breach or (not heartbeat_ok) or (not power_ok):
        return 'TRIP -> safe state'      # latched until manual reset
    return 'permit'

def watchdog(last_pet_ns, now_ns, window_ns):
    # miss the window by any margin -> trip; silence is not safe
    if (now_ns - last_pet_ns) > window_ns:
        return 'TRIP'
    return 'ok'

def pet_deadline(loop_period_ns, misses_allowed=2):
    # allow a small number of missed ticks before declaring dead
    return loop_period_ns * (misses_allowed + 1)

def runaway_suppressed(density_after_inject, critical_density):
    # above the critical density, collisional drag beats the E-field
    return density_after_inject >= critical_density

def avalanche_headroom(n_inject, n_crit, margin=1.5):
    # inject enough to clear the threshold with margin
    return n_inject >= margin * n_crit

def stress_ratio(hoop_stress_MPa, allowable_MPa):
    return hoop_stress_MPa / allowable_MPa

def coil_permit(ratio, trip_at=1.0, warn_at=0.85):
    if ratio >= trip_at:
        return 'TRIP -> dump'      # never operate an overstressed coil
    if ratio >= warn_at:
        return 'WARN -> limit current'
    return 'permit'

# the design-point specification sits at ratio ~3-3.9: infeasible as-is
assert coil_permit(3.4) == 'TRIP -> dump'

def confinement_margin(phi_plug, phi_min, phi_max):
    # normalized distance inside the confining-potential band
    if phi_plug < phi_min:
        return -1.0                # below floor: confinement collapsing
    span = phi_max - phi_min
    return (phi_plug - phi_min) / span

def envelope_action(margin, dphi_dt, rate_limit):
    if margin <= 0 or dphi_dt < -rate_limit:
        return 'TRIP -> controlled ride-down'
    return 'permit'

def dec_action(load_fault, dv_dt, plasma_ok, limits):
    # isolate first, ask questions later
    if load_fault or abs(dv_dt) > limits['dv_dt']:
        return 'ISOLATE load -> ride-through on plasma side'
    if not plasma_ok:
        return 'DECOUPLE DEC -> controlled ride-down'
    return 'run'

def quench_chain(normal_zone_voltage, threshold_V, confirm_windows, dump):
    if normal_zone_voltage <= threshold_V:
        return 'permit'
    # brief confirmation to reject noise, then irreversible dump
    if confirm_windows >= 2:
        dump.fire()
        return 'DUMP fired -> energy to resistors'
    return 'arming'

def hotspot_ok(detect_ms, dump_time_ms, allowable_ms):
    return (detect_ms + dump_time_ms) <= allowable_ms

def cryo_permit(temp_K, target_K, flow_ok, tol_K=0.5):
    # margin band around the operating temperature, flow present
    return abs(temp_K - target_K) <= tol_K and flow_ok

def energize_gate(cryo_ok, vac_ok):
    # both preconditions AND-ed into the energization permissive
    return cryo_ok and vac_ok

def authorized(action, level, second_person=False):
    REQUIRED = {'abort':0, 'command':1, 'relax_soft_limit':2,
                'bypass_interlock':3}
    need = REQUIRED[action]
    ok = level >= need
    if action == 'bypass_interlock':
        ok = ok and second_person       # two-person rule
    return ok

def manual_trip(button_pressed, failsafe):
    # direct path to the failsafe; no model, no network, no permission check
    if button_pressed:
        failsafe.latch_trip()
        return 'TRIP -> safe state (hardwired)'
    return 'armed'

def replay(recorded_inputs, reflex_fn):
    # deterministic reflex + recorded inputs -> reproduce every decision
    outputs = [reflex_fn(x) for x in recorded_inputs]
    return outputs

def matches_live(replayed, recorded_outputs):
    # replay must reproduce the live decisions bit-for-bit
    return all(a == b for a, b in zip(replayed, recorded_outputs))

def commission_case(inject_fault, expected_response, reflex, latency_budget_ns):
    t0 = clock_ns()
    inject_fault()
    resp = reflex.observe_response()
    latency = clock_ns() - t0
    return (resp == expected_response) and (latency <= latency_budget_ns)

def respond(fault_class, table):
    # look up, don't reason; default to the safest action
    return table.get(fault_class, ('failsafe', 'trip', 'safe_state'))
